INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('0bc7f093-bef0-4f1a-852c-4b75ebf54838','Arcane Signet','Sinete Arcano','arcane signet','sinete arcano','arena','{"set":"frc","number":"20"}','[{"name_pt":"Sinete Arcano","type_pt":"Artefato","text_pt":"{T}: Adicione um mana de qualquer cor da identidade de cor de seu comandante.","flavor_pt":"“Tudo está em progresso... assim como nós. Que sempre possamos saber exatamente quem somos.”\n — Jace, para Tam","mana_cost":"{2}","name_en":"Arcane Signet"}]','{"id":"57dec142-1301-4055-b6db-cb252cd34a7d","set":"lcc","number":"299","hires":false}','normal','Artifact',3,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('4457ed35-7c10-48c8-9776-456485fdf070','Lightning Bolt','Raio','lightning bolt','raio','arena','{"set":"msc","number":"806"}','[{"name_pt":"Raio","type_pt":"Mágica Instantânea","text_pt":"Raio causa 3 pontos de dano a qualquer alvo.","flavor_pt":"“Sou o deus do trovão, senhor do relâmpago selvagem. Os céus devem tremer quando fala O Poderoso Thor!”","mana_cost":"{R}","name_en":"Lightning Bolt"}]','{"id":"914243e1-a097-4e15-8bb7-5f83205a66f3","set":"clb","number":"401","hires":false}','normal','Instant',159,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('68954295-54e3-4303-a6bc-fc4547a4e3a3','Llanowar Elves','Elfos de Llanowar','llanowar elves','elfos de llanowar','arena','{"set":"fdn","number":"429"}','[{"name_pt":"Elfos de Llanowar","type_pt":"Criatura — Elfo Druida","text_pt":"{T}: Adicione {G}.","flavor_pt":null,"mana_cost":"{G}","name_en":"Llanowar Elves"}]','{"id":"163b64cb-4f61-4bd7-bdd8-69548c59a2cf","set":"m12","number":"182","hires":true}','normal','Creature — Elf Druid',54,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('6ad8011d-3471-4369-9d68-b264cc027487','Sol Ring','Anel Solar','sol ring','anel solar','arena','{"set":"tle","number":"316"}','[{"name_pt":"Anel Solar","type_pt":"Artefato","text_pt":"{T}: Adicione {C}{C}.","flavor_pt":"\"A estrada a nossa frente é desafiadora. Um século de lutas deixou o mundo marcado e dividido. Mas com a ajuda do Avatar, podemos colocá-lo de volta no caminho certo e iniciar uma nova era de amor e paz.”\n — Zuko","mana_cost":"{1}","name_en":"Sol Ring"}]','{"id":"c0fb3d2e-f2a0-416a-a2e3-52b19d6879a5","set":"lcc","number":"313","hires":false}','normal','Artifact',1,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('76372327-41ec-4516-abff-3b612e073629','Kona, Rescue Beastie','Konia, Monstrinha de Resgate','kona rescue beastie','konia monstrinha de resgate','arena','{"set":"dsk","number":"358"}','[{"name_pt":"Konia, Monstrinha de Resgate","type_pt":"Criatura Lendária — Besta Sobrevivente","text_pt":"Sobrevivência — No início de sua segunda fase principal, se Konia estiver virada, você pode colocar no campo de batalha um card de permanente de sua mão.","flavor_pt":null,"mana_cost":"{3}{G}","name_en":"Kona, Rescue Beastie"}]',NULL,'normal','Legendary Creature — Beast Survivor',2532,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('7f77a84e-5a4b-4834-aefa-3cecc175ae8e','Jace, the Mind Sculptor','Jace, o Escultor de Mentes','jace the mind sculptor','jace o escultor de mentes','arena','{"set":"blc","number":"93"}','[{"name_pt":"Jace, o Escultor de Mentes","type_pt":"Planeswalker Lendário — Jace","text_pt":"Olhe o card do topo do grimório do jogador alvo. Você pode colocar aquele card no fundo do grimório daquele jogador.\nCompre três cards e depois coloque dois cards de sua mão no topo de seu grimório em qualquer ordem.\nDevolva a criatura alvo para a mão de seu dono.\nExile todos os card do grimório do jogador alvo, depois, aquele jogador embaralha a mão no próprio grimório.","flavor_pt":null,"mana_cost":"{2}{U}{U}","name_en":"Jace, the Mind Sculptor"}]','{"id":"b0d2128a-9d36-41f1-9fc2-19d7a50e9310","set":"wwk","number":"31","hires":false}','normal','Legendary Planeswalker — Jace',3247,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('8b755881-a72d-4e21-a369-d2924eb4585a','Cultivate','Cultivar','cultivate','cultivar','arena','{"set":"fic","number":"300"}','[{"name_pt":"Cultivar","type_pt":"Feitiço","text_pt":"Procure em seu grimório até dois cards de terreno básico, revele-os, coloque um deles no campo de batalha virado e o outro na sua mão e, depois, embaralhe.","flavor_pt":"\"Dizem que não cresce grama nem flores em Midgar. Mas, por alguma razão, as flores crescem sem problemas aqui.\"","mana_cost":"{2}{G}","name_en":"Cultivate"}]','{"id":"53e58830-4674-4d1d-8731-dd34c93f5cfb","set":"lcc","number":"235","hires":false}','normal','Sorcery',20,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('b1544f21-7e98-461b-aed5-e748b0168c52','Swords to Plowshares','Espadas em Arados','swords to plowshares','espadas em arados | espadas em arados emerito da tregua','arena','{"set":"sos","number":"13"}','[{"name_pt":"Espadas em Arados","type_pt":"Mágica Instantânea","text_pt":"Exile a criatura alvo. Seu controlador ganha uma quantidade de pontos de vida igual ao seu poder.","flavor_pt":null,"mana_cost":"{W}","name_en":"Swords to Plowshares"},{"name_pt":"Emérito da Trégua","type_pt":"Criatura — Felino Clérigo","text_pt":"Quando esta criatura entra, o jogador alvo cria uma ficha de criatura Nanquíneo branca e preta 1/1 com voar. Depois, se um oponente controlar mais criaturas que você, esta criatura se torna preparada.","flavor_pt":null,"mana_cost":"{1}{W}{W}","name_en":"Emeritus of Truce"}]','{"id":"54e28b95-4523-4acf-9804-a8012467022a","set":"lcc","number":"137","hires":false}','normal','Instant',11,1);
INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('b34bb2dc-c1af-4d77-b0b3-a0fb342a5fc6','Forest','Floresta','forest','floresta','arena','{"set":"ana","number":"5"}','[{"name_pt":"Floresta","type_pt":"Terreno Básico — Floresta","text_pt":"","flavor_pt":"A Floresta Nacional Olímpica abriga uma das maiores florestas tropicais temperadas do mundo. Árvores centenárias, copas densas e bosques cobertos de musgo compartilham um ecossistema interconectado repleto de vida vegetal e animal.","mana_cost":null,"name_en":"Forest"}]','{"id":"c084e00a-cf46-47b4-a112-769839b54153","set":"ths","number":"249","hires":true}','normal','Basic Land — Forest',NULL,1);
