INSERT OR REPLACE INTO cards (oracle_id,name_en,name_pt,search_en,search_pt,source,text_print,faces,pt_print,layout,type_line,edhrec_rank,commander) VALUES ('45d49831-548a-4a0e-9a18-9f7397913895','Tovolar, Dire Overlord // Tovolar, the Midnight Scourge','Tovolar, Soberano Medonho // Tovolar, Flagelo da Meia-noite','tovolar dire overlord | tovolar dire overlord tovolar the midnight scourge','tovolar soberano medonho tovolar flagelo da meia noite','arena','{"set":"mid","number":"311"}','[{"name_pt":"Tovolar, Soberano Medonho","type_pt":"Criatura Lendária — Humano Lobisomem","text_pt":"Toda vez que um Lobo ou Lobisomem que você controla causar dano de combate a um jogador, compre um card.\nNo início de sua manutenção, se você controlar três ou mais Lobos e/ou Lobisomens, torna-se noite. Depois, transforme qualquer número de Humanos Lobisomens que você controla.\nDiurno","flavor_pt":null,"mana_cost":"{1}{R}{G}","name_en":"Tovolar, Dire Overlord"},{"name_pt":"Tovolar, Flagelo da Meia-noite","type_pt":"Criatura Lendária — Lobisomem","text_pt":"Toda vez que um Lobo ou Lobisomem que você controla causar dano de combate a um jogador, compre um card.\n{X}{R}{G}: O Lobo ou Lobisomem alvo que você controla recebe +X/+0 e ganha atropelar até o final do turno.\nNoturno","flavor_pt":null,"mana_cost":null,"name_en":"Tovolar, the Midnight Scourge"}]','{"id":"a2893557-ca2d-44b7-9ccf-d012267d5a71","set":"mid","number":"246","hires":false}','transform','Legendary Creature — Human Werewolf // Legendary Creature — Werewolf',7252,1);
